def restore_sevii_water_text(path,source):
    if str(path)!="src/data/wild_encounters.json":return source
    for key,old in ORIGINAL_SEVII_WATER.items():
        label,method=key.split("|")
        i=source.index('"'+method+'": {',source.index('"base_label": "'+label+'"'))
        current=BALANCED_SEVII_WATER[key]
        assert source[i:i+len(current)]==current,key
        source=source[:i]+old+source[i+len(current):]
    return source
def prior_sevii_water_source(path):
    return restore_sevii_water_text(path,prior_sevii_land_source(path).decode("utf-8")).encode("utf-8")
def restore_prior_sevii_water_text(path,source):
    return restore_sevii_water_text(path,restore_prior_sevii_land_text(path,source))
